package org.sleepwell.app;
import android.content.*;
/** Only Arm tonight reads these preferences. Recurring admission and delayed/manual starts are separate. */
final class ArmedWaitSettings {static final String CHARGING="automaticWaitCharging",SCREEN="automaticWaitScreenOff";static ArmedWaitConditions read(SharedPreferences preferences){Object charging=preferences.getAll().get(CHARGING),screen=preferences.getAll().get(SCREEN);if(charging!=null&&!(charging instanceof Boolean)||screen!=null&&!(screen instanceof Boolean))throw new IllegalArgumentException("Review armed wait conditions and save them again.");return new ArmedWaitConditions(Boolean.TRUE.equals(charging),Boolean.TRUE.equals(screen));}static SharedPreferences.Editor put(SharedPreferences.Editor editor,ArmedWaitConditions value){return editor.putBoolean(CHARGING,value.charging).putBoolean(SCREEN,value.screenOff);}static Intent extras(Intent intent,ArmedWaitConditions value){return intent.putExtra(CHARGING,value.charging).putExtra(SCREEN,value.screenOff);}static ArmedWaitConditions intent(Intent intent){Object charging=intent.getExtras()==null?null:intent.getExtras().get(CHARGING),screen=intent.getExtras()==null?null:intent.getExtras().get(SCREEN);if(charging!=null&&!(charging instanceof Boolean)||screen!=null&&!(screen instanceof Boolean))throw new IllegalArgumentException("Invalid armed wait conditions");return new ArmedWaitConditions(Boolean.TRUE.equals(charging),Boolean.TRUE.equals(screen));}private ArmedWaitSettings(){}}
